function binaryItem() {
  try { return $('Binary From Attachment1').item; } catch (e) {}
  try { return $('Binary From MIME Export1').item; } catch (e) {}
  return null;
}

const sd = $getWorkflowStaticData('global');
if (!sd.appendedCorfs) sd.appendedCorfs = {};

const trackerRows = $('Load Work Order Form Tracker').all().map(i => i.json);
const trackedCorfs = new Set();
for (const row of trackerRows) {
  const c = normCorf(row.CORF ?? row.corf ?? '');
  if (c) trackedCorfs.add(c);
}

const src = binaryItem();
const prep = (src && src.json) || {};
const prepBinary = (src && src.binary) || {};
const listResp = $json;
const status = listResp.statusCode ?? 200;
const body = listResp.body ?? listResp;
const existing = (status >= 200 && status < 300 && body.value) ? body.value : [];
const fileName = prep.msg_file_name;
const match = existing.find(v => String(v.name).toLowerCase() === String(fileName).toLowerCase());
const exists = !!match;
const existingSize = match?.size ?? null;
const isEmptyOnSharePoint = exists && (existingSize === 0 || existingSize === null);
const emailId = String(prep.email_id || prep.id || '');
const corf = normCorf(prep.corf || prep.client_order_reference || corfFromSubject(prep.subject));
const inTracker = corfKnown(corf, trackedCorfs, sd.appendedCorfs);

return {
  json: {
    ...prep,
    email_id: emailId,
    corf,
    client_order_reference: corf,
    file_exists: exists,
    existing_sharepoint_size: existingSize,
    is_empty_on_sharepoint: isEmptyOnSharePoint,
    skipped_tracker: inTracker,
    skip_upload: inTracker || (exists && !isEmptyOnSharePoint),
    should_upload: prep.has_binary && !inTracker && (!exists || isEmptyOnSharePoint),
    target_folder_ok: status >= 200 && status < 300,
    target_folder_status: status
  },
  binary: prepBinary
};

function byteLength(b) {
  if (!b) return 0;
  if (typeof b.fileSize === 'number' && b.fileSize > 0) return b.fileSize;
  if (typeof b.data !== 'string' || !b.data) return 0;
  const pad = (b.data.match(/=+$/) || [''])[0].length;
  return Math.floor((b.data.length * 3) / 4) - pad;
}

