const driveId = $('Get BCC library drive4').first().json.id;
const trackerRows = $('Load Work Order Form Tracker').all().map(i => i.json);
const regional = (() => {
  try {
    return $('Resolve Regional Inbox Folders1').first().json.folder_by_category || {};
  } catch (e) {
    return {};
  }
})();

const sd = $getWorkflowStaticData('global');
sd.appendedCorfs = {};

const trackedCorfs = new Set();
for (const row of trackerRows) {
  const c = normCorf(row.CORF ?? row.corf ?? '');
  if (c) trackedCorfs.add(c);
}

const seenInBatch = new Set();

const SP_BASE = 'RR Job imports and JIS/Orders';
const SP_BY_REGION = {
  'RR- South': `${SP_BASE}/RR-South/inbox`,
  'RR- North': `${SP_BASE}/RR-North/inbox`,
  'D&M': `${SP_BASE}/D&M`
};

const CAT_EXACT = {
  'RR- South': 'RR- South',
  'RR- North': 'RR- North',
  'D&M': 'D&M',
  'D & M': 'D&M'
};

function matchedCategory(categories) {
  if (!Array.isArray(categories)) return null;
  for (const raw of categories) {
    const c = String(raw).trim();
    if (CAT_EXACT[c]) return CAT_EXACT[c];
  }
  for (const raw of categories) {
    const c = String(raw).trim();
    const lower = c.toLowerCase();
    if (lower.includes('south') && lower.includes('rr')) return 'RR- South';
    if (lower.includes('north')) return 'RR- North';
    if (lower.includes('d&m') || lower.includes('d & m')) return 'D&M';
  }
  return null;
}

function mapCategoryToSharePoint(categories) {
  const cat = matchedCategory(categories);
  return cat ? (SP_BY_REGION[cat] || null) : null;
}

function mapCategoryToOutlook(categories) {
  const cat = matchedCategory(categories);
  if (!cat) return null;
  return regional[cat] || null;
}

function safeFileName(subject, received, id) {
  const date = String(received || '').slice(0, 10).replace(/-/g, '');
  const subj = String(subject || 'message')
    .replace(/[<>:"/\\|?*]/g, '_')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 80);
  const shortId = String(id || '').slice(-8);
  return `${date || 'nodate'}_${subj || 'message'}_${shortId}.msg`.replace(/\s/g, '_');
}

function buildRow(msg) {
  const id = msg.id;
  const sharepoint_path = mapCategoryToSharePoint(msg.categories);
  const outlook = mapCategoryToOutlook(msg.categories);
  const regionCat = matchedCategory(msg.categories);
  const corf = corfFromSubject(msg.subject);

  if (!sharepoint_path && !outlook) return null;
  if (corfKnown(corf, trackedCorfs, sd.appendedCorfs)) return null;
  if (corf && seenInBatch.has(corf)) return null;
  if (corf) seenInBatch.add(corf);

  const sourceAlreadyInTarget = !!(outlook?.id && msg.parentFolderId && msg.parentFolderId === outlook.id);

  return {
    ...msg,
    email_id: id,
    internet_message_id: msg.internetMessageId || null,
    drive_id: driveId,
    sharepoint_path: sharepoint_path || null,
    needs_sharepoint_upload: !!sharepoint_path,
    outlook_folder_id: outlook?.id || null,
    outlook_folder_path: outlook?.path || null,
    matched_category: regionCat,
    corf,
    client_order_reference: corf,
    msg_file_name: safeFileName(msg.subject, msg.receivedDateTime, msg.id),
    skip_mailbox_copy: !outlook?.id || sourceAlreadyInTarget,
    skip_upload: false,
    mailbox_action: 'copy'
  };
}

const out = [];
for (const item of $input.all()) {
  const msg = item.json || {};
  if (!msg.id) continue;
  const row = buildRow(msg);
  if (row) out.push({ json: row });
}

if (!out.length) {
  return [{ json: { skip_upload: true, _no_regional_messages: true } }];
}
return out;

const seen = new Set();
const merged = [];
const byCategory = [];
const expandItems = $('Expand Category Queries1').all();
const fetchItems = $input.all();

for (let idx = 0; idx < fetchItems.length; idx++) {
  const req = expandItems[idx]?.json || {};
  const body = fetchItems[idx].json || {};
  const vals = body.value || [];
  byCategory.push({ category: req.category, count: vals.length, error: body.error || null });
  for (const m of vals) {
    if (!m?.id || seen.has(m.id)) continue;
    seen.add(m.id);
    merged.push(m);
  }
}

merged.sort((a, b) => String(b.receivedDateTime || '').localeCompare(String(a.receivedDateTime || '')));

return [{
  json: {
    value: merged,
    count: merged.length,
    fetch_by_category: byCategory
  }
}];

return [
  { json: { category: 'RR- South', filter: "categories/any(a:a+eq+'RR-+South')" } },
